using UnityEngine;using System.Collections.Generic;
public class BlackGoldPunchVFX:MonoBehaviour {
 public Transform RuntimeRoot=>root?root.transform:null;

 public float chargeStart=.45f,releaseTime=3.05f,peakTime=3.1167f,endTime=3.65f;public Transform fist;Transform upperArm,forearm;public Vector3[] trajectory;public float sampleRate=120;public bool IsVisible=>root&&root.activeSelf;public bool IsCharging{get;private set;}public bool IsPunching{get;private set;}GameObject root;Mesh gold,ink;Material goldMaterial,inkMaterial;
 class Geometry {public List<Vector3> v=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Color> c=new List<Color>();public List<int> t=new List<int>();public void Clear(){v.Clear();uv.Clear();c.Clear();t.Clear();}public void Quad(Vector3 a,Vector3 b,Vector3 d,Vector3 e,Color color){int k=v.Count;v.AddRange(new[]{a,b,d,e});uv.AddRange(new[]{new Vector2(0,0),new Vector2(0,1),new Vector2(1,1),new Vector2(1,0)});for(int i=0;i<4;i++)c.Add(color);t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}public void Ribbon(Vector3 a,Vector3 b,Vector3 side,float width,float tip,Color color){Quad(a-side*width,a+side*width,b+side*tip,b-side*tip,color);}public void Apply(Mesh m){m.Clear();m.SetVertices(v);m.SetUVs(0,uv);m.SetColors(c);m.SetTriangles(t,0);m.RecalculateBounds();}}
 Geometry g=new Geometry(),dark=new Geometry();
 public void BindLive(Transform hand,Transform upper,Transform lower){fist=hand;upperArm=upper;forearm=lower;}
 void Build(){root=new GameObject("J063 black gold charge and punch"){hideFlags=HideFlags.DontSave};root.layer=gameObject.layer;goldMaterial=new Material(Shader.Find("Boss/BlackGoldFlame")){hideFlags=HideFlags.HideAndDontSave};inkMaterial=new Material(Shader.Find("Boss/BlackGoldInk")){hideFlags=HideFlags.HideAndDontSave};gold=Layer("Gold energy",goldMaterial);ink=Layer("Black ink silhouette",inkMaterial);}
 Mesh Layer(string name,Material material){var go=new GameObject(name){hideFlags=HideFlags.DontSave};go.layer=gameObject.layer;go.transform.SetParent(root.transform,false);var m=new Mesh(){name=name,hideFlags=HideFlags.HideAndDontSave};go.AddComponent<MeshFilter>().sharedMesh=m;go.AddComponent<MeshRenderer>().sharedMaterial=material;return m;}
 public void Sample(float time,bool active,Camera camera){if(!root)Build();IsCharging=active&&time>=chargeStart&&time<releaseTime;IsPunching=active&&time>=releaseTime&&time<endTime;root.SetActive(IsCharging||IsPunching);if(!root.activeSelf||!fist)return;if(!upperArm){var bones=fist.root.GetComponentsInChildren<Transform>();upperArm=System.Array.Find(bones,b=>b.name=="Right_UpperArm");forearm=System.Array.Find(bones,b=>b.name=="Right_LowerArm");}if(!upperArm||!forearm)return;
 g.Clear();dark.Clear();goldMaterial.SetFloat("_Phase",time);inkMaterial.SetFloat("_Phase",time);float q=Mathf.InverseLerp(chargeStart,releaseTime,time),fade=IsCharging?Mathf.Clamp01((time-chargeStart)*4):Mathf.Pow(Mathf.Clamp01(1-(time-peakTime)/.52f),1.4f);float power=IsCharging?.25f+.45f*q:.9f;Vector3 upperDir=(forearm.position-upperArm.position).normalized,lowerDir=(fist.position-forearm.position).normalized;
 // The entire stream is rebuilt from shoulder, elbow and wrist in the current pose.
 // UV motion travels from shoulder (0) to fist (1); no camera-facing spiral around the character.
 for(int k=0;k<6;k++){var points=new Vector3[41];for(int j=0;j<41;j++){float u=j/40f;Vector3 axis=Vector3.Slerp(upperDir,lowerDir,Mathf.SmoothStep(0,1,Mathf.InverseLerp(.36f,.64f,u)));Vector3 side=Vector3.Cross(axis,Vector3.forward).normalized;if(side.sqrMagnitude<.1f)side=Vector3.Cross(axis,Vector3.up).normalized;Vector3 normal=Vector3.Cross(axis,side).normalized;Vector3 path=u<.5f?Vector3.Lerp(upperArm.position,forearm.position,u*2):Vector3.Lerp(forearm.position,fist.position,(u-.5f)*2);float angle=k*Mathf.PI*2/6+u*2.7f+Mathf.Sin(u*8-time*3+k)*.20f;float radius=Mathf.Lerp(.052f,.035f,u)+.006f*Mathf.Sin(u*12-time*5+k);points[j]=path+(side*Mathf.Cos(angle)+normal*Mathf.Sin(angle))*radius;}Strip(points,.016f+.007f*q,power*fade,camera,true,k);}
 // Small moving packets make the shoulder-to-wrist direction readable during the hold.
 for(int k=0;k<5;k++){float travel=Mathf.Repeat(time*(IsCharging?.7f:1.8f)+k*.2f,1);var points=new Vector3[12];for(int j=0;j<12;j++){float u=Mathf.Clamp01(travel-.16f+j/11f*.16f);Vector3 axis=Vector3.Slerp(upperDir,lowerDir,Mathf.SmoothStep(0,1,Mathf.InverseLerp(.36f,.64f,u)));Vector3 side=Vector3.Cross(axis,Vector3.forward).normalized;if(side.sqrMagnitude<.1f)side=Vector3.Cross(axis,Vector3.up).normalized;Vector3 normal=Vector3.Cross(axis,side).normalized;Vector3 path=u<.5f?Vector3.Lerp(upperArm.position,forearm.position,u*2):Vector3.Lerp(forearm.position,fist.position,(u-.5f)*2);float angle=k*2.4f+u*2.7f;points[j]=path+(side*Mathf.Cos(angle)+normal*Mathf.Sin(angle))*Mathf.Lerp(.055f,.038f,u);}Strip(points,.017f,power*fade*.6f,camera,false,k);}
 if(IsPunching){float grow=Mathf.Clamp01((time-releaseTime)/.07f);Vector3 side=Vector3.Cross(lowerDir,Vector3.up).normalized;if(side.sqrMagnitude<.1f)side=Vector3.right;Vector3 normal=Vector3.Cross(lowerDir,side).normalized;for(int k=0;k<6;k++){var points=new Vector3[24];for(int j=0;j<24;j++){float u=j/23f,a=k*Mathf.PI*2/6+u*1.2f;float r=(.038f+Mathf.Sin(u*Mathf.PI)*.045f*grow)*(1-u*.7f);points[j]=Vector3.Lerp(forearm.position,fist.position,Mathf.Min(u*2,1))+lowerDir*Mathf.Max(0,u-.5f)*(.28f*grow)+(side*Mathf.Cos(a)+normal*Mathf.Sin(a))*r;}Strip(points,.026f,fade*.65f,camera,true,k);}}
 if(IsPunching)ImpactBurst(time,camera,lowerDir);g.Apply(gold);dark.Apply(ink);}
 void ImpactBurst(float time,Camera camera,Vector3 dir){float age=time-(peakTime-.025f);if(age<0||age>.27f)return;float opening=1-Mathf.Exp(-age*60),fade=Mathf.Pow(Mathf.Clamp01(1-age/.27f),1.5f);Vector3 side=Vector3.Cross(dir,Vector3.up).normalized;if(side.sqrMagnitude<.1f)side=Vector3.right;Vector3 up=Vector3.Cross(side,dir).normalized;Vector3 origin=fist.position;
 // Compact directional fist wind: broad soft core, wispy rear edges, no expanding cage.
 for(int k=0;k<8;k++){var points=new Vector3[30];float angle=k*Mathf.PI*2/8;for(int j=0;j<30;j++){float u=j/29f;float radius=Mathf.Sin(u*Mathf.PI)*(.055f+.018f*Hash(k));Vector3 radial=side*Mathf.Cos(angle+u*.55f)+up*Mathf.Sin(angle+u*.55f);points[j]=origin+dir*(-.12f+u*(.21f+.24f*opening))+radial*radius+up*Mathf.Sin(u*10-time*12+k)*.008f;}Strip(points,.042f,fade*.72f,camera,true,k);}
 // Peripheral wind wisps align with the punch rather than spreading into a circular wave.
 for(int k=0;k<7;k++){var points=new Vector3[18];float angle=k*2.39996f;Vector3 radial=side*Mathf.Cos(angle)+up*Mathf.Sin(angle);for(int j=0;j<18;j++){float u=j/17f;points[j]=origin+dir*(-.18f+u*.48f*opening)+radial*(.11f*(1-u)+.015f)+up*Mathf.Sin(u*4+k)*.015f;}Strip(points,.013f,fade*.55f,camera,false,k);}
 for(int k=0;k<14;k++){float angle=k*2.39996f;Vector3 radial=side*Mathf.Cos(angle)+up*Mathf.Sin(angle);float travel=age*(.5f+Hash(k));Vector3 center=origin+dir*(.06f+travel)+radial*(.04f+travel*.25f);var points=new Vector3[8];for(int j=0;j<8;j++)points[j]=center+dir*((j/7f-.5f)*(.025f+.035f*Hash(k+4)));Strip(points,.004f,fade*.7f,camera,false,k);}}
 void Strip(Vector3[] points,float width,float opacity,Camera camera,bool smoke,float phase){for(int j=0;j<points.Length-1;j++){float u=j/(float)(points.Length-1),v=(j+1)/(float)(points.Length-1);Vector3 tangent=(points[j+1]-points[j]).normalized,side=Vector3.Cross(camera.transform.forward,tangent).normalized;float w=width*Mathf.Pow(Mathf.Sin(Mathf.Lerp(.08f,3.06f,u)),.7f),w2=width*Mathf.Pow(Mathf.Sin(Mathf.Lerp(.08f,3.06f,v)),.7f);AddStrip(g,points[j],points[j+1],side,w*.55f,w2*.55f,u,v,phase,new Color(1,1,1,opacity*.65f));AddStrip(dark,points[j],points[j+1],side,w*2f,w2*2f,u,v,phase,new Color(.008f,.007f,.006f,Mathf.Min(.95f,opacity*1.65f)));}}
 void AddStrip(Geometry geo,Vector3 a,Vector3 b,Vector3 side,float wa,float wb,float u,float v,float phase,Color color){int k=geo.v.Count;geo.Quad(a-side*wa,a+side*wa,b+side*wb,b-side*wb,color);geo.uv[k]=new Vector2(u,0);geo.uv[k+1]=new Vector2(u,1);geo.uv[k+2]=new Vector2(v,1);geo.uv[k+3]=new Vector2(v,0);}
 static float Hash(int i)=>Mathf.Repeat(Mathf.Sin((i+1)*127.1f)*43758.5453f,1);
 void OnDestroy(){if(root)Destroy(root);if(gold)Destroy(gold);if(ink)Destroy(ink);if(goldMaterial)Destroy(goldMaterial);if(inkMaterial)Destroy(inkMaterial);}
}
